using System;using System.IO;using System.Text;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Web.Script.Serialization;
// Public only for offline verification in the x86 editor's test mode.
public static class FamilyProbe {
 static readonly JavaScriptSerializer json=new JavaScriptSerializer{MaxJsonLength=2000000};
 static void Need(bool yes,string message){if(!yes)throw new InvalidDataException(message);}
 static byte[] Wave(float[] values,int rate,int channels){using(var m=new MemoryStream())using(var w=new BinaryWriter(m)){w.Write(Encoding.ASCII.GetBytes("RIFF"));w.Write(36+values.Length*4);w.Write(Encoding.ASCII.GetBytes("WAVEfmt "));w.Write(16);w.Write((ushort)3);w.Write((ushort)channels);w.Write(rate);w.Write(rate*channels*4);w.Write((ushort)(channels*4));w.Write((ushort)32);w.Write(Encoding.ASCII.GetBytes("data"));w.Write(values.Length*4);foreach(float v in values)w.Write(v);w.Flush();return m.ToArray();}}
 static void ImportChecks(string folder,List<string> checks){
  string root=Path.Combine(folder,"ir-conversion");Directory.CreateDirectory(root);var slots=new MultiIRSlots();
  var longIR=new float[24000];longIR[0]=.5f;longIR[40]=-.1f;string first=Path.Combine(root,"long.wav");File.WriteAllBytes(first,Wave(longIR,48000,1));var source=File.ReadAllBytes(first);var converted=IRImport.Read(first);Need(converted.TailWindow&&converted.SourceFrames==24000,"Long IR was not adapted");
  var slot=slots.Import(1,first,new IRLevels.Profile(),root);Need(MultiIRSlots.Read(slot).SequenceEqual(converted.Coefficients),"Canonical IR differs");Need(File.ReadAllBytes(slot.sourcePath).SequenceEqual(source)&&File.ReadAllBytes(first).SequenceEqual(source),"Original source not preserved");
  string saved=Path.Combine(root,"slots.json");slots.Save(saved);var loaded=MultiIRSlots.Load(saved);Need(MultiIRSlots.Read(loaded.slots[1]).SequenceEqual(converted.Coefficients)&&loaded.slots[1].sourcePath==slot.sourcePath,"Converted IR cannot be reloaded");
  string backup=Path.Combine(root,"backup");Directory.CreateDirectory(backup);slots.Backup(backup);Need(File.ReadAllBytes(Path.Combine(backup,"IR2-source.wav")).SequenceEqual(source),"Source missing from backup");
  var previous=slots.slots[1];string invalid=Path.Combine(root,"invalid.wav");File.WriteAllText(invalid,"invalid IR");bool rejected=false;try{slots.Import(1,invalid,new IRLevels.Profile(),root);}catch{rejected=true;}Need(rejected&&ReferenceEquals(previous,slots.slots[1]),"Failed import changed the selected IR");
  checks.Add("General IR conversion: canonical cache, exact reload, source preservation, backup and failed-import atomicity");
 }
 static void Fixture(string folder,int product,int mixed=0){Directory.CreateDirectory(folder);for(int i=1;i<=12;i++){var preset=new{schema="L6Preset",version=2,data=new{device=mixed!=0&&i==8?mixed:product,device_version=0x02020000,meta=new{name="SYNTHETIC "+i},tone=new{FixtureOnly=i}}};for(int r=1;r<=2;r++)File.WriteAllText(Path.Combine(folder,string.Format("preset-{0:00}-read-{1}.catl6p",i,r)),json.Serialize(preset));}File.WriteAllText(Path.Combine(folder,"READS-COMPLETE.txt"),"SYNTHETIC OFFLINE FIXTURE");}
 public static string Run(string folder){Directory.CreateDirectory(folder);var checks=new List<string>();ImportChecks(folder,checks);
  foreach(int id in new[]{2424833,2424834,2424835}){
   FamilyProfile.ConnectedProduct=id;string dir=Path.Combine(folder,id.ToString());Fixture(dir,id);string backup=Path.Combine(dir,"fixture.catl6a");FirmwareCodec.CreateVerifiedBackup(dir,backup);Need(FamilyProfile.BackupProduct(backup)==id,"Archive product was changed");checks.Add(FamilyProfile.Name(id)+": 12 double reads, archive product retained, checksums and evidence verified");
   Need(FamilyProfile.TargetIndex(new[]{12345,id},false,id)==1,"Normal target index");var recovery=FamilyProfile.RecoveryIdentity(1,2428928,backup);Need(Convert.ToInt32(recovery["setDeviceIdentity_newDeviceProductIDKey"])==id,"Recovery model changed");checks.Add(FamilyProfile.Name(id)+": normal selection and recovery identity retain verified model");
   string cross=Path.Combine(folder,id+"-cross");Fixture(cross,id);FamilyProfile.ConnectedProduct=id==2424833?2424834:2424833;bool rejected=false;try{FirmwareCodec.CreateVerifiedBackup(cross,Path.Combine(cross,"bad.catl6a"));}catch(InvalidDataException){rejected=true;}Need(rejected,"Cross-model target accepted");checks.Add(FamilyProfile.Name(id)+": backup for different connected model rejected");
   FamilyProfile.ConnectedProduct=id;string mixed=Path.Combine(folder,id+"-mixed");Fixture(mixed,id,id==2424833?2424835:2424833);rejected=false;try{FirmwareCodec.CreateVerifiedBackup(mixed,Path.Combine(mixed,"bad.catl6a"));}catch(InvalidDataException){rejected=true;}Need(rejected,"Mixed products accepted");checks.Add(FamilyProfile.Name(id)+": mixed product preset read rejected");
  }
  FamilyProfile.ConnectedProduct=0;Need(!FamilyProfile.IsModel(2428928)&&!FamilyProfile.IsModel(2428929),"Bootloader inferred as model");checks.Add("Unidentified bootloaders excluded from normal model identities");
  foreach(var ids in new[]{new[]{2424833,2424834},new[]{123456},new[]{2428928}}){bool rejected=false;try{FamilyProfile.TargetIndex(ids,false,2424833);}catch(InvalidDataException){rejected=true;}Need(rejected,"Ambiguous or non-normal target selected");}checks.Add("Multiple Catalyst devices, unknown products and unidentified recovery targets rejected");
  Need(!AppDomain.CurrentDomain.GetAssemblies().Any(a=>a.GetName().Name=="EngineCLIWrapper"),"Offline fixtures loaded USB wrapper");checks.Add("No vendor USB wrapper loaded");
  return json.Serialize(new{passed=true,hardware_accessed=false,synthetic_fixtures=true,component_sha256=FirmwareCodec.Hash(File.ReadAllBytes(typeof(FamilyProbe).Assembly.Location)),checks=checks});
 }
 public static string Parity(string model,string original,string folder){Directory.CreateDirectory(folder);byte[] baseline=File.ReadAllBytes(original);Need(FirmwareCodec.Hash(baseline)=="5ea2edc9b8aec952a05c5c1b6832579eae02e82ee65e265d0a084171f8e51901","Wrong baseline app");var assembly=Assembly.Load(baseline);string first=Path.Combine(folder,"original.ctf"),second=Path.Combine(folder,"family.ctf");
  foreach(var entry in new[]{Tuple.Create(assembly,first),Tuple.Create(typeof(FamilyProbe).Assembly,second)}){var app=entry.Item1.GetType("OneClickApp",true);var args=new[]{"--nam-candidate",Path.GetFullPath(model),"-",Path.GetFullPath(entry.Item2),"auto"};var callArgs=new object[]{args,0};app.GetMethod("NamCommands",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,callArgs);}
  Need(File.ReadAllBytes(first).SequenceEqual(File.ReadAllBytes(second)),"Family firmware differs from proven generator");
  string backup=Path.Combine(folder,"baseline-backup");Fixture(backup,2424833);string oldBackup=Path.Combine(backup,"baseline.catl6a");assembly.GetType("FirmwareCodec",true).GetMethod("CreateVerifiedBackup").Invoke(null,new object[]{backup,oldBackup});string newBackup=Path.Combine(backup,"family.catl6a");FamilyProfile.ConnectedProduct=2424833;FirmwareCodec.CreateVerifiedBackup(backup,newBackup);Need(File.ReadAllBytes(oldBackup).SequenceEqual(File.ReadAllBytes(newBackup)),"CX60 archive format changed");
  Need(!AppDomain.CurrentDomain.GetAssemblies().Any(a=>a.GetName().Name=="EngineCLIWrapper"),"Parity test loaded USB wrapper");return json.Serialize(new{passed=true,hardware_accessed=false,component_sha256=FirmwareCodec.Hash(File.ReadAllBytes(typeof(FamilyProbe).Assembly.Location)),firmware_byte_identical=true,firmware_sha256=FirmwareCodec.Hash(File.ReadAllBytes(second)),CX60_backup_byte_identical=true,no_USB_wrapper_loaded=true});
 }
}
